SET
    assignee_user_id = #{item.assigneeUserId}
  , status = #{item.status}
  , assign_reason_type = #{item.assignReasonType}
  , done_at = #{item.doneAt}
  , skipped_reason = #{item.skippedReason}
  , update_user_id = #{updateUserId}
  , update_program = #{updateProgram}
WHERE
    housework_task_id = #{item.houseworkTaskId}

