SET
    assignee_user_id = NULL
  , assign_reason_type = '9'
  , update_user_id = #{loginUserId}
  , update_program = #{program}
WHERE
    household_id = #{householdId}
  AND status = '0'
  AND assignee_user_id = #{assigneeUserId}

